"""Mock data for the product prototype (product/), generated by the simulator, not typed by hand.

Four patients practise for two weeks in the data-grounded simulator (configs/sim_pnt.yaml) with the
trained agent choosing difficulty and hints (models/ppo_pnt_seed0.zip):
  Maria  demo_maria   conduction aphasia, fitted to 9 real patients (docs/PERSONAS.md)
  James  demo_james   anomic aphasia, fitted to 6 real patients
  Ruth   severe       severe cohort (stops practising for the last days: a caseload flag)
  David  mild_anomic  mild cohort
Each patient keeps what they learned from day to day (item learning carries over; fatigue resets).

James's clinician-teaching moment is computed for real: a simulated clinician who gives a semantic
cue after a wrong-word error overrides the agent 8 times on James's sessions, DITTO-style tuning
with accepted-choice anchors runs on the trained agent (agents/ditto.py), and adoption is measured
on held-out James states; then James practises 4 more sessions with the tuned agent.

Writes product/mock/data.json and builds product/index.html from product/template.html (data and
the 24 Twemoji pictures of data/items.json inlined, so the page is a single self-contained file).
Usage:  uv run python -m scripts.build_product_mock
"""
from __future__ import annotations

import base64
import collections
import json
from datetime import date, timedelta

import numpy as np
from sb3_contrib import MaskablePPO

from agents.ditto import Demo, action_probs, ditto
from agents.ppo import PPOPolicy
from core.config import load_clinical, load_yaml, resolve
from core.masks import ACTION_CUES, ACTION_TIERS, action_index
from envs.aphasia_env import AphasiaEnv, load_env_config
from scripts.calibrate_pnt import theta_equivalent
from sim.config import load_sim
from sim.items import ItemSelector, load_items
from sim.population import make_patients
from sim.session import run_session
from train.ditto_ppo import categorise, collect_states

SIM = "configs/sim_pnt.yaml"
MODEL = "models/ppo_pnt_seed0.zip"
END = date(2026, 11, 6)          # last practice day shown (the demo is on Nov 7-8)
HINT_NAMES = {"none": "no hint", "first_sound": "first sound", "first_letter": "first letter",
              "sentence_frame": "sentence frame", "semantic": "meaning hint"}
PATIENTS = [
    {"id": "maria", "preset": "demo_maria", "name": "Maria Alvarez", "first": "Maria", "age": 62,
     "type": "Conduction aphasia", "months_post": 8, "helper": "her husband, Luis",
     "about": "Retired teacher. The word is there but the sounds come out wrong ('tat' for 'cat').",
     "days": [0, 1, 2, 4, 5, 7, 8, 9, 11, 12, 13], "level": 1, "goal_minutes": 75,
     "personal_words": ["Sofia", "Mateo", "tomato", "rose", "chalk"],
     "fitted": "Fitted to 9 real patients with conduction aphasia (MAPPD)"},
    {"id": "james", "preset": "demo_james", "name": "James Carter", "first": "James", "age": 58,
     "type": "Anomic aphasia", "months_post": 5, "helper": "his daughter, Kim",
     "about": "Former bus driver. Knows what he means, often says a related word or describes it.",
     "days": [0, 1, 3, 4, 6, 7, 8, 10, 11, 13], "level": 2, "goal_minutes": 75,
     "personal_words": ["Kim", "bus", "coffee", "Detroit"],
     "fitted": "Fitted to 6 real patients with anomic aphasia (MAPPD)"},
    {"id": "ruth", "preset": "severe", "name": "Ruth Okafor", "first": "Ruth", "age": 71,
     "type": "Severe aphasia (mixed)", "months_post": 3, "helper": "her son, Daniel",
     "about": "Few words come; tires quickly. Practises with her son in the evening.",
     "days": [0, 1, 2, 3, 5, 6, 8, 9], "level": 1, "goal_minutes": 60,
     "personal_words": ["Daniel", "church", "tea"],
     "fitted": "Severe cohort of the data-grounded simulator"},
    {"id": "david", "preset": "mild_anomic", "name": "David Kim", "first": "David", "age": 49,
     "type": "Mild anomic aphasia", "months_post": 11, "helper": "practises on his own",
     "about": "Back at part-time work. Occasional word-finding pauses, mostly with less common words.",
     "days": [0, 1, 2, 3, 4, 7, 8, 9, 10, 11, 12, 13], "level": 2, "goal_minutes": 90,
     "personal_words": ["spreadsheet", "Seoul", "guitar"],
     "fitted": "Mild anomic cohort of the data-grounded simulator"},
]


def reason(prev: dict | None, t: dict, prev_tier: int) -> str:
    """Plain-language reason for the agent's choice, from what it could see."""
    if t.get("probe"):
        return "Review: a word practised earlier, shown again without a hint."
    move = ("moved up a level" if t["tier"] > prev_tier else "moved down a level" if t["tier"] < prev_tier
            else "kept the level")
    if prev is None:
        return "First picture of the session."
    if prev["outcome"]:
        return f"Last answer correct, so no hint; {move}."
    err = {"sound": "a sound error", "meaning": "a wrong word", "no_response": "no answer"}[prev["error_type"]]
    return f"After {err}, gave the {HINT_NAMES[t['cue']]}; {move}."


def play_days(policy, patient, cfg, clinical, bank, n_sessions, seed, start_tier):
    sessions = []
    tier = start_tier
    for s in range(n_sessions):
        patient.fatigue, patient.fail_streak = 0.0, 0
        sel = ItemSelector(bank, np.random.default_rng([seed, s]), cfg.review_probes)
        run_cfg = cfg.model_copy(update={"session": cfg.session.model_copy(update={"start_tier": tier})})
        res = run_session(policy, patient, sel, run_cfg, clinical, n_trials=30)
        sessions.append(res)
        agent = [t for t in res.trace if not t.get("probe")]
        tier = int(round(np.mean([t["tier"] for t in agent[-6:]]))) if agent else tier
    return sessions


def summarise(res, clinical) -> dict:
    tr = res.trace
    trials, prev, prev_tier = [], None, tr[0]["tier"] if tr else 1
    for t in tr:
        trials.append({"word": t["word"], "level": int(t["tier"]), "hint": t["cue"], "correct": bool(t["outcome"]),
                       "error": t["error_type"], "seconds": float(t["response_time"]), "review": bool(t.get("probe")),
                       "reason": reason(prev, t, prev_tier)})
        if not t.get("probe"):
            prev_tier = t["tier"]
        prev = t
    n = len(tr)
    no_hint = sum(1 for t in tr if t["outcome"] and t["cue"] == "none")
    with_hint = sum(1 for t in tr if t["outcome"] and t["cue"] != "none")
    errs = collections.Counter(t["error_type"] for t in tr if not t["outcome"])
    probes = [t for t in tr if t.get("probe")]
    minutes = sum(t["response_time"] + 6.0 for t in tr) / 60 * 1.6     # x1.6: hints, feedback and repeat-the-word time
    return {"pictures": n, "named_without_hint": no_hint / n, "named_with_hint": with_hint / n,
            "errors": {"sound": errs["sound"], "wrong_word": errs["meaning"], "no_answer": errs["no_response"]},
            "review_recall": float(np.mean([p["outcome"] for p in probes])) if probes else None,
            "mean_level": float(np.mean([t["tier"] for t in tr])), "ended_early": bool(res.quit),
            "minutes": round(minutes, 1), "trials": trials}


def cue_after(sessions: list[dict], error: str) -> dict:
    c = collections.Counter()
    for s in sessions:
        for a, b in zip(s["trials"], s["trials"][1:]):
            if not a["correct"] and a["error"] == error and not b["review"]:
                c[b["hint"]] += 1
    n = sum(c.values())
    return {k: round(v / n, 2) for k, v in c.items()} if n else {}


def james_teaching(ref, cfg, clinical) -> tuple[MaskablePPO, dict]:
    rule = {"after_error": "meaning", "cue": "semantic"}
    env = AphasiaEnv(cohort="demo_james", split="test", sim_cfg=cfg)
    pool = categorise(collect_states(ref, env, range(0, 40)), rule)
    held = categorise(collect_states(ref, env, range(100, 160)), rule)
    cand = []
    for s in pool["matching"]:
        a = int(np.argmax(action_probs(ref, s["obs"][None], s["mask"][None])[0]))
        b = action_index(int(ACTION_TIERS[a]), rule["cue"])
        if ACTION_CUES[a] != rule["cue"] and s["mask"][b]:
            cand.append(Demo(s["obs"], s["mask"], b))
    demos = [cand[i] for i in np.random.default_rng(0).choice(len(cand), size=8, replace=False)]
    anchors = [(s["obs"], s["mask"]) for s in pool["other_errors"] + pool["unrelated"]]
    c = load_yaml("configs/ditto.yaml")
    tuned, _ = ditto(ref, demos, c["rounds"], c["samples_per_state"], c["beta"], c["learning_rate"],
                     c["gradient_steps_per_round"], 0, anchors=anchors, anchor_weight=c["anchor_weight"])

    def share(model, states, cue=None, same=False):
        o, m = np.stack([s["obs"] for s in states]), np.stack([s["mask"] for s in states])
        a = action_probs(model, o, m).argmax(1)
        if same:
            return float(np.mean(a == action_probs(ref, o, m).argmax(1)))
        return float(np.mean(np.array(ACTION_CUES)[a] == cue))
    other = held["other_errors"] + held["unrelated"]
    return tuned, {"n_overrides": len(demos), "rule": "After a wrong-word error, give a meaning hint",
                   "before": round(share(ref, held["matching"], "semantic"), 2),
                   "after": round(share(tuned, held["matching"], "semantic"), 2),
                   "other_unchanged": round(share(tuned, other, same=True), 2),
                   "held_out_states": len(held["matching"])}


def main() -> None:
    cfg, clinical = load_sim(SIM), load_clinical()
    bank = load_items(cfg.items)
    env_cfg = load_env_config()
    ref = MaskablePPO.load(str(resolve(MODEL)), device="cpu")
    policy = PPOPolicy(ref, clinical, env_cfg)
    real = np.array([float(r["theta_t"]) for r in csv_rows("data/pnt_thetas.csv")])
    b = np.array([float(r["irt_difficulty_t"]) for r in csv_rows("data/pnt_items.csv")])
    out = {"generated_by": "scripts/build_product_mock.py", "simulated": True, "as_of": END.isoformat(),
           "note": "All patients and sessions are simulated by the data-grounded patient simulator. "
                   "Composite personas, not real people.", "patients": []}
    for k, p in enumerate(PATIENTS):
        spec = make_patients(cfg, p["preset"], "test", 1, 0, start=k)[0]
        patient, _ = spec.build(bank, cfg, clinical)
        theta = theta_equivalent(float(patient.retrieval_probabilities().mean()), b)
        results = play_days(policy, patient, cfg, clinical, bank, len(p["days"]), k, p["level"])
        start = END - timedelta(days=13)
        sessions = []
        for d, res in zip(p["days"], results):
            s = summarise(res, clinical)
            s["date"] = (start + timedelta(days=d)).isoformat()
            sessions.append(s)
        rec = {k2: v for k2, v in p.items() if k2 not in ("preset", "days", "level")}
        rec.update({"pnt_score": round(theta, 1), "pnt_percentile": int(round(100 * np.mean(real <= theta))),
                    "sessions": sessions,
                    "plan": {"level": p["level"], "hint_order": "match_error", "pictures_per_session": 12,
                             "max_attempts": 3, "advance_rule": "80% named without a hint over 2 sessions",
                             "session_minutes": 15, "days_per_week": 5, "personal_words": p["personal_words"],
                             "break_after_misses": 3},
                    "cue_after": {"sound": cue_after(sessions, "sound"), "wrong_word": cue_after(sessions, "meaning")}})
        if p["id"] == "james":
            tuned, teach = james_teaching(ref, cfg, clinical)
            tuned_policy = PPOPolicy(tuned, clinical, env_cfg)
            after = [summarise(r, clinical) for r in play_days(tuned_policy, patient, cfg, clinical, bank, 4, 99,
                                                                 p["level"])]
            teach["sessions_after"] = [{**s, "date": (END + timedelta(days=i + 1)).isoformat()} for i, s in enumerate(after)]
            teach["cue_after_wrong_word_after"] = cue_after(after, "meaning")
            rec["teaching"] = teach
        out["patients"].append(rec)
        last = sessions[-3:]
        print(f"{p['first']:6s} PNT {theta:.1f} ({rec['pnt_percentile']}th)  sessions {len(sessions)}  "
              f"no-hint last3 {np.mean([s['named_without_hint'] for s in last]):.2f}  cue after wrong word {rec['cue_after']['wrong_word']}")
    james = next(x for x in out["patients"] if x["id"] == "james")
    print("James teaching:", {k: v for k, v in james["teaching"].items() if k != "sessions_after"})

    mock_dir = resolve("product/mock")
    mock_dir.mkdir(parents=True, exist_ok=True)
    (mock_dir / "data.json").write_text(json.dumps(out, indent=1))
    items = json.loads(resolve("data/items.json").read_text())["items"]
    pics = {}
    for it in items:
        svg = resolve("frontend") / it["image_path"]
        pics[it["exercise_id"]] = "data:image/svg+xml;base64," + base64.b64encode(svg.read_bytes()).decode()
    tpl = resolve("product/template.html").read_text()
    html = (tpl.replace("/*__MOCK_DATA__*/null", json.dumps(out, separators=(",", ":")))
               .replace("/*__ITEMS__*/null", json.dumps(items, separators=(",", ":")))
               .replace("/*__PICTURES__*/null", json.dumps(pics, separators=(",", ":"))))
    # product/index.html opens from disk or any static server; product/page.html is the same page without
    # the document wrapper (for hosts that add their own, e.g. a published Artifact).
    wrapper = ('<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n'
               '<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n'
               '<style>[hidden]{display:none!important}img{max-width:100%}</style>\n</head>\n<body>\n')
    resolve("product/page.html").write_text(html)
    html_full = wrapper + html + "\n</body>\n</html>\n"
    resolve("product/index.html").write_text(html_full)
    print(f"wrote product/mock/data.json and product/index.html ({len(html) // 1024} KB)")


def csv_rows(path):
    import csv
    return list(csv.DictReader(open(resolve(path))))


if __name__ == "__main__":
    main()
